#include <stdio.h>

void reverse(int *arr, int n) {
    int *l = arr;
    int *r = arr + n - 1;
    while (l < r) {
        int tmp = *l;
        *l = *r;
        *r = tmp;
        l++;
        r--;
    }
}

int main(void) {
    int n;
    int a[100];
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) return 1;
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    reverse(a, n);
    for (int i = 0; i < n; i++) printf("%d%c", a[i], i == n - 1 ? '\n' : ' ');
    return 0;
}
